import numpy as np, itertools, sys
TB=[0,5,10,45,50,55,100,105,110,115,150,200,205,250]
TW=[0,10,50,100,150,190,200]
B,W,A=np.meshgrid(np.arange(0,255,5),np.arange(0,210,10),np.arange(10,230,10),indexing='ij')
B,W,A=B.ravel(),W.ravel(),A.ravel()
F=np.where(A>100,5,0)
T=np.isin(B,TB)&np.isin(W,TW)
def tdiv(x,c): return np.trunc(x/c).astype(int)
atoms={'a':A,'B':B,'w':W,'f':F,'200':np.full_like(A,200),'100':np.full_like(A,100)}
ex=dict(atoms)
for (n1,e1),(n2,e2) in itertools.combinations(atoms.items(),2):
    ex[f'({n1}+{n2})']=e1+e2; ex[f'({n1}-{n2})']=e1-e2; ex[f'({n2}-{n1})']=e2-e1
for n1,n2,n3 in itertools.combinations(['a','B','w','f'],3):
    for s in itertools.product([1,-1],repeat=3):
        ex[f'({s[0]}{n1}{s[1]:+}{n2}{s[2]:+}{n3})']=s[0]*atoms[n1]+s[1]*atoms[n2]+s[2]*atoms[n3]
base=dict(ex)
for n,e in base.items():
    for c in [10,20,50,100]:
        ex[f'{n}/{c}*{c}']=tdiv(e,c)*c
        ex[f'{n}%{c}']=e-tdiv(e,c)*c
print(len(ex),len(base))
lim0=W+A>200; fun0=A+F>B
def st(l,f): return np.where(l,1,np.where(f,2,0))
R=st(lim0,fun0)
which=sys.argv[1]
res=[]
items=list(ex.items()); bitems=list(base.items())
for n1,e1 in items:
  for n2,e2 in items:
    for on,p in (('>',e1>e2),('>=',e1>=e2)):
      S=st(p,fun0) if which=='L' else st(lim0,p)
      d=S!=R
      if d[T].any(): continue
      c=d.sum()
      if c: res.append((int(c),f'{n1} {on} {n2}'))
res.sort(reverse=True)
for r in res[:100]: print(r)
print(len(res))
EOF
