import itertools, sys
which=sys.argv[1]
TB=[0,5,10,45,50,55,100,105,110,115,150,200,205,250]
TW=[0,10,50,100,150,190,200]
if which=='F':
    pts=[(B,0,a) for B in range(0,255,5) for a in range(10,210,10)]
    names=['a','B','f']; tested=[p[0] in TB for p in pts]
else:
    pts=[(250,w,a) for w in range(0,210,10) for a in range(10,230,10)]
    names=['a','w','f']; tested=[p[1] in TW for p in pts]
def val(n,B,w,a):
    f=5 if a>100 else 0
    return {'a':a,'B':B,'w':w,'f':f}[n]
cols={n:[val(n,*p) for p in pts] for n in names}
for c in [5,10,50,100,200]: cols[str(c)]=[c]*len(pts)
atoms=dict(cols)
ex=dict(atoms)
for (n1,e1),(n2,e2) in itertools.combinations(atoms.items(),2):
    ex[f'({n1}+{n2})']=[x+y for x,y in zip(e1,e2)]
    ex[f'({n1}-{n2})']=[x-y for x,y in zip(e1,e2)]
    ex[f'({n2}-{n1})']=[y-x for x,y in zip(e1,e2)]
for s in itertools.product([1,-1],repeat=2):
    e=[x+s[0]*y+s[1]*z for x,y,z in zip(*[cols[n] for n in names])]
    ex[f'({names[0]}{s[0]:+}{names[1]}{s[1]:+}{names[2]})']=e
base=dict(ex)
td=lambda x,c:int(x/c)
for n,e in base.items():
    for c in [10,20,50,100]:
        ex[f'{n}/{c}*{c}']=[td(x,c)*c for x in e]
        ex[f'{n}/{c}']=[td(x,c) for x in e]
        ex[f'{n}%{c}']=[x-td(x,c)*c for x in e]
ex={k:tuple(v) for k,v in ex.items()}
# dedupe
seen={};
for k,v in ex.items(): seen.setdefault(v,k)
ex={k:v for v,k in seen.items()}
print(len(ex))
ref=[ (a+(5 if a>100 else 0)>B) if which=='F' else (w+a>200) for B,w,a in pts]
res=[]
items=list(ex.items())
N=len(pts)
for n1,e1 in items:
  for n2,e2 in items:
    gt=[x>y for x,y in zip(e1,e2)]
    ge=[x>=y for x,y in zip(e1,e2)]
    for on,p in (('>',gt),('>=',ge)):
      ok=True; d=0
      for i in range(N):
        if p[i]!=ref[i]:
          if tested[i]: ok=False;break
          d+=1
      if ok and d: res.append((d,f'{n1} {on} {n2}'))
res.sort(reverse=True)
for r in res[:150]: print(r)
print(len(res))
EOF
